package com.horizen.economy;

import com.horizen.economy.database.Database;
import com.horizen.economy.economy.*;
import com.horizen.economy.gui.MenuHolder;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.util.io.BukkitObjectInputStream;import org.bukkit.util.io.BukkitObjectOutputStream;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.scheduler.BukkitTask;
import java.io.*;import java.sql.*;import java.util.*;import java.util.concurrent.ThreadLocalRandom;

public final class HorizenEconomy extends JavaPlugin implements Listener, CommandExecutor, TabCompleter {
 private Database db; private EconomyService economy; private final Map<UUID,String> chatActions=new java.util.concurrent.ConcurrentHashMap<>(); private final Map<UUID,org.bukkit.permissions.PermissionAttachment> managerAttachments=new java.util.concurrent.ConcurrentHashMap<>();
 private String symbol; private boolean compact;
 @Override public void onEnable(){saveDefaultConfig();for(String f:List.of("messages.yml","shop.yml","upgrades.yml","adminshop.yml","orders.yml","auctions.yml"))saveResource(f,false);symbol=getConfig().getString("currency.symbol","रू");compact=getConfig().getBoolean("currency.compact-format",true);
  try{db=new Database(this);economy=new EconomyService(db,getConfig().getLong("limits.max-balance",9_000_000_000_000_000_000L));}catch(Exception e){getLogger().severe("SQLite initialization failed: "+e.getMessage());getServer().getPluginManager().disablePlugin(this);return;}
  getServer().getPluginManager().registerEvents(this,this);getServer().getScheduler().runTaskTimer(this,this::maintenance,1200L,1200L);String[] cmds={"balance","pay","baltop","bank","eco","shop","sell","upgrade","opshop","adminshop","hop","order","auction"};for(String c:cmds){PluginCommand pc=getCommand(c);if(pc!=null){pc.setExecutor(this);pc.setTabCompleter(this);}}
  for(Player p:Bukkit.getOnlinePlayers())initialize(p);getLogger().info("HorizenEconomy enabled; SQLite WAL storage ready.");
 }
 @Override public void onDisable(){if(db!=null)try{db.backup();db.close();}catch(SQLException e){getLogger().severe("Database close error: "+e.getMessage());}}
 private void initialize(Player p){try{db.ensurePlayer(p.getUniqueId(),p.getName(),getConfig().getLong("currency.starting-balance",0));refreshName(p);attachManagerPermissions(p);}catch(SQLException e){p.sendMessage("§cEconomy data could not be initialized.");getLogger().severe(e.getMessage());}}
 private String money(long n){return Money.format(n,compact,symbol);} private void msg(CommandSender s,String m){s.sendMessage("§8[§5Horizen§8] §r"+ChatColor.translateAlternateColorCodes('&',m));}
 private long amount(String s){long n=Money.parse(s);if(n<getConfig().getLong("limits.min-transaction",1)||n>getConfig().getLong("limits.max-payment",1_000_000_000_000_000L))throw new IllegalArgumentException("Amount outside configured limits.");return n;}
 private boolean manager(UUID id){try{return db.hasManager(id);}catch(SQLException e){return false;}}
 private void attachManagerPermissions(Player p){if(!manager(p.getUniqueId()))return;org.bukkit.permissions.PermissionAttachment old=managerAttachments.remove(p.getUniqueId());if(old!=null)p.removeAttachment(old);org.bukkit.permissions.PermissionAttachment at=p.addAttachment(this);at.setPermission("horizeneconomy.manager",true);for(String power:List.of("fly","gamemode","teleport","heal","feed","give"))at.setPermission("horizeneconomy.manager."+power,true);managerAttachments.put(p.getUniqueId(),at);}
 private void refreshName(Player p){String prefix=manager(p.getUniqueId())?ChatColor.translateAlternateColorCodes('&',getConfig().getString("manager.prefix","&c[Manager]"))+" ":"";p.setPlayerListName(prefix+p.getName());}
 @EventHandler public void join(PlayerJoinEvent e){initialize(e.getPlayer());}
 @EventHandler public void quit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId();chatActions.remove(id);org.bukkit.permissions.PermissionAttachment at=managerAttachments.remove(id);if(at!=null)e.getPlayer().removeAttachment(at);}
 @EventHandler public void chat(AsyncPlayerChatEvent e){Player p=e.getPlayer();String action=chatActions.remove(p.getUniqueId());if(action==null){if(manager(p.getUniqueId()))e.setFormat(ChatColor.translateAlternateColorCodes('&',getConfig().getString("manager.prefix","&c[Manager]"))+" §f"+p.getName()+"§7: §f"+e.getMessage());return;}e.setCancelled(true);Bukkit.getScheduler().runTask(this,()->processChatAmount(p,action,e.getMessage()));}
 private void processChatAmount(Player p,String action,String input){try{long n=amount(input);if(action.equals("deposit")){db.tx(c->{try(PreparedStatement a=c.prepareStatement("UPDATE wallets SET balance=balance-? WHERE uuid=? AND balance>=?")){a.setLong(1,n);a.setString(2,p.getUniqueId().toString());a.setLong(3,n);if(a.executeUpdate()!=1)throw new IllegalStateException("Insufficient wallet funds.");}try(PreparedStatement a=c.prepareStatement("UPDATE bank SET balance=balance+? WHERE uuid=? AND balance<=?")){a.setLong(1,n);a.setString(2,p.getUniqueId().toString());a.setLong(3,Long.MAX_VALUE-n);if(a.executeUpdate()!=1)throw new IllegalStateException("Bank balance limit reached.");}EconomyService.log(c,p.getUniqueId(),"BANK_DEPOSIT",-n,"deposit");return null;});msg(p,"Deposited "+money(n)+" into your bank.");}
 else if(action.equals("withdraw")){db.tx(c->{try(PreparedStatement a=c.prepareStatement("UPDATE bank SET balance=balance-? WHERE uuid=? AND balance>=?")){a.setLong(1,n);a.setString(2,p.getUniqueId().toString());a.setLong(3,n);if(a.executeUpdate()!=1)throw new IllegalStateException("Insufficient bank funds.");}try(PreparedStatement a=c.prepareStatement("UPDATE wallets SET balance=balance+? WHERE uuid=? AND balance<=?")){a.setLong(1,n);a.setString(2,p.getUniqueId().toString());a.setLong(3,getConfig().getLong("limits.max-balance",Long.MAX_VALUE)-n);if(a.executeUpdate()!=1)throw new IllegalStateException("Wallet balance limit reached.");}EconomyService.log(c,p.getUniqueId(),"BANK_WITHDRAW",n,"withdraw");return null;});msg(p,"Withdrew "+money(n)+" from your bank.");}}
 catch(Exception ex){msg(p,"§c"+safe(ex));}}
 private String safe(Exception e){return e.getMessage()==null?"Transaction failed.":e.getMessage();}

 @Override public boolean onCommand(CommandSender s,Command command,String label,String[] a){String c=command.getName().toLowerCase(Locale.ROOT);try{
  switch(c){case "balance"->{if(!(s instanceof Player p))return true;msg(s,"Wallet: §6"+money(db.balance(p.getUniqueId()))+" §7| Bank: §6"+money(db.bank(p.getUniqueId())));}
   case "pay"->{if(!(s instanceof Player p))return true;if(a.length!=2){msg(s,"Usage: /pay <player> <amount>");return true;}OfflinePlayer target=Bukkit.getOfflinePlayer(a[0]);if(target.getUniqueId()==null||(!target.hasPlayedBefore()&&target.getName()==null)){msg(s,"Player not found.");return true;}long n=amount(a[1]);economy.transfer(p.getUniqueId(),target.getUniqueId(),target.getName()==null?a[0]:target.getName(),n,"PAY");msg(p,"Paid "+money(n)+" to "+(target.getName()==null?a[0]:target.getName())+".");if(target.isOnline())msg(target.getPlayer(),"You received "+money(n)+" from "+p.getName()+".");}
   case "baltop"->baltop(s);
   case "bank"->{if(!(s instanceof Player p))return true;if(a.length>0){if(a[0].equalsIgnoreCase("history")){bankHistory(p);return true;}if(a.length!=2||(!a[0].equalsIgnoreCase("deposit")&&!a[0].equalsIgnoreCase("withdraw"))){msg(s,"Usage: /bank [deposit|withdraw|history] [amount]");return true;}long n=amount(a[1]);processChatAmount(p,a[0].toLowerCase(Locale.ROOT),Long.toString(n));}else openBank(p);}
   case "eco"->{if(!s.hasPermission("horizeneconomy.admin"))return noPerm(s);if(a.length==2&&a[0].equalsIgnoreCase("audit")){OfflinePlayer who=Bukkit.getOfflinePlayer(a[1]);try(PreparedStatement q=db.raw().prepareStatement("SELECT kind,amount,details,created_at FROM transactions WHERE uuid=? ORDER BY id DESC LIMIT 20")){q.setString(1,who.getUniqueId().toString());try(ResultSet r=q.executeQuery()){while(r.next())msg(s,r.getString(1)+" "+r.getLong(2)+" "+r.getString(3)+" "+new Date(r.getLong(4)));}}return true;}if(a.length!=3){msg(s,"Usage: /eco <give|take|set|audit> <player> [amount]");return true;}OfflinePlayer t=Bukkit.getOfflinePlayer(a[1]);long n=amount(a[2]);switch(a[0].toLowerCase(Locale.ROOT)){case "give"->economy.adjust(t.getUniqueId(),a[1],n,"ADMIN_GIVE");case "take"->economy.adjust(t.getUniqueId(),a[1],-n,"ADMIN_TAKE");case "set"->economy.set(t.getUniqueId(),a[1],n);default->{msg(s,"Use give, take or set.");return true;}}msg(s,"Updated "+a[1]+" balance.");}
   case "shop"->{if(s instanceof Player p)openShop(p);}
   case "sell"->{if(!(s instanceof Player p))return true;sell(p,a);}
   case "upgrade"->{if(s instanceof Player p)openUpgrade(p);}
   case "opshop"->{if(!(s instanceof Player p))return true;opshop(p,a);}
   case "adminshop"->{if(!(s instanceof Player p))return true;if(!manager(p.getUniqueId()))return noPerm(s);openAdminShop(p);}
   case "hop"->{if(!(s instanceof Player p))return true;hop(p,a);}
   case "order"->{if(!(s instanceof Player p))return true;order(p,a);}
   case "auction"->{if(!(s instanceof Player p))return true;auction(p,a);}
   case "sethome"->{if(!(s instanceof Player p))return true;setHome(p,a);}
   case "home"->{if(!(s instanceof Player p))return true;goHome(p,a);}
  }
 }catch(Exception e){msg(s,"§c"+safe(e));getLogger().warning("Command /"+c+" failed: "+e.getMessage());}return true;}
 private boolean noPerm(CommandSender s){msg(s,"&cYou do not have permission.");return true;}
 private void baltop(CommandSender s)throws SQLException{msg(s,"§d§lRichest players");try(PreparedStatement p=db.raw().prepareStatement("SELECT name,balance FROM wallets ORDER BY balance DESC,name COLLATE NOCASE ASC LIMIT 10");ResultSet r=p.executeQuery()){int i=1;while(r.next())msg(s,"§7"+i+++". §f"+r.getString(1)+" §8— §6"+money(r.getLong(2)));}}

 private ItemStack item(Material m,String name,String... lore){ItemStack it=new ItemStack(m);ItemMeta im=it.getItemMeta();im.setDisplayName("§5"+name);im.setLore(Arrays.asList(lore));it.setItemMeta(im);return it;}
 private Inventory menu(Player p,String id,String title,int size){MenuHolder holder=new MenuHolder(id);Inventory inv=Bukkit.createInventory(holder,size,title);holder.setInventory(inv);p.openInventory(inv);return inv;}
 private void openBank(Player p){Inventory inv=menu(p,"bank","§0✦ §5Horizen Bank",27);inv.setItem(11,item(Material.GOLD_INGOT,"Deposit","§7Click then use /bank deposit <amount>"));inv.setItem(13,item(Material.SUNFLOWER,"Account balance","§7Wallet: §6"+money(dbBalance(p))+"","§7Bank: §6"+money(dbBank(p))));inv.setItem(15,item(Material.CHEST,"Withdraw","§7Click then use /bank withdraw <amount>"));inv.setItem(22,item(Material.BOOK,"Transaction history","§7Click to view your recent bank activity"));}
 private long dbBalance(Player p){try{return db.balance(p.getUniqueId());}catch(Exception e){return 0;}}private long dbBank(Player p){try{return db.bank(p.getUniqueId());}catch(Exception e){return 0;}}
 private void openShop(Player p){Inventory inv=menu(p,"shop","§0✦ §5Horizen Market",54);String[] cats={"Farming","Commands","Gear","Ores"};Material[] icons={Material.WHEAT,Material.COMPASS,Material.DIAMOND_CHESTPLATE,Material.DIAMOND};for(int i=0;i<cats.length;i++)inv.setItem(10+i*2,item(icons[i],cats[i],"§7Browse "+cats[i]+" items"));inv.setItem(29,item(Material.WRITABLE_BOOK,"Private Orders","§7Permanent unlock: §6"+money(getConfig().getLong("orders.unlock-price")),"§7Anonymous player buying orders"));inv.setItem(33,item(Material.ANVIL,"Auction House","§7Permanent unlock: §6"+money(getConfig().getLong("auctions.unlock-price")),"§7Anonymous item auctions"));inv.setItem(49,item(Material.BARRIER,"Close"));}
 private void openCategory(Player p,String cat){Inventory inv=menu(p,"category:"+cat,"§0§5Shop » "+cat,54);org.bukkit.configuration.file.YamlConfiguration shop=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(new File(getDataFolder(),"shop.yml"));var items=shop.getConfigurationSection("categories."+cat+".items");if(items==null){msg(p,"No items configured in this category.");return;}int slot=0;for(String key:items.getKeys(false)){if(slot>=45)break;Material m=Material.matchMaterial(key);if(m==null)continue;long buy=items.getLong(key+".buy",-1),sell=items.getLong(key+".sell",-1);inv.setItem(slot++,item(m,key,"§7Buy: §6"+(buy<0?"Disabled":money(buy)),"§7Sell: §6"+(sell<0?"Disabled":money(sell)),"§eLeft-click: buy 1","§eRight-click: sell 1"));}inv.setItem(49,item(Material.ARROW,"Back"));}
 private void openUpgrade(Player p){Inventory inv=menu(p,"upgrade","§0✦ §5Permanent Upgrades",27);String[] k={"ender-storage","homes","sell-limit"};Material[] m={Material.ENDER_CHEST,Material.RED_BED,Material.HOPPER};String[] names={"Ender Storage","Homes","Sell Limit"};for(int i=0;i<3;i++){int level=0;try{level=db.upgrade(p.getUniqueId(),k[i]);}catch(Exception ignored){}List<Integer> prices=getConfig().getIntegerList("upgrades."+k[i]+".prices");long price=level<prices.size()?prices.get(level):-1;inv.setItem(10+i*3,item(m[i],names[i],"§7Current level: §f"+level,"§7Next price: §6"+(price<0?"MAX":money(price)),"§eClick to upgrade"));}}
 private void openAdminShop(Player p){Inventory inv=menu(p,"adminshop","§0✦ §4Manager Admin Shop",54);org.bukkit.configuration.file.YamlConfiguration y=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(new File(getDataFolder(),"adminshop.yml"));int slot=0;for(String cat:y.getConfigurationSection("categories").getKeys(false)){for(String name:y.getStringList("categories."+cat+".items")){Material m=Material.matchMaterial(name);if(m!=null&&slot<45)inv.setItem(slot++,item(m,name,"§7Category: "+cat,"§aFree manager access","§eClick to receive"));}}}
 private void sell(Player p,String[] a){String mode=a.length==0?"hand":a[0].toLowerCase(Locale.ROOT);if(mode.equals("hand")){ItemStack it=p.getInventory().getItemInMainHand();sellStack(p,it,false);}else if(mode.equals("all")){int level=0;try{level=db.upgrade(p.getUniqueId(),"sell-limit");}catch(Exception ignored){}int limit=getConfig().getInt("sell.base-item-limit",128)+level*getConfig().getInt("sell.items-per-level",128);int sold=0;for(int slot=0;slot< p.getInventory().getStorageContents().length&&sold<limit;slot++){ItemStack it=p.getInventory().getItem(slot);if(it==null||it.getType().isAir()||it.hasItemMeta())continue;int take=Math.min(it.getAmount(),limit-sold);ItemStack part=new ItemStack(it.getType(),take);long price=shopPrice(it.getType(),false);if(price<=0)continue;ItemStack removed=new ItemStack(it.getType(),take);it.setAmount(it.getAmount()-take);if(it.getAmount()==0)p.getInventory().setItem(slot,null);try{economy.adjust(p.getUniqueId(),p.getName(),Math.multiplyExact(price,take),"SHOP_SELL");sold+=take;}catch(Exception ex){p.getInventory().addItem(removed);msg(p,"§c"+safe(ex));break;}}msg(p,"Sold "+sold+" item(s). Sell limit: "+limit+".");}else msg(p,"Usage: /sell [all|hand]");}
 private void sellStack(Player p,ItemStack it,boolean all){if(it==null||it.getType().isAir()||it.hasItemMeta()){msg(p,"Hold a plain shop item without custom metadata.");return;}long price=shopPrice(it.getType(),false);if(price<=0){msg(p,"This item cannot be sold here.");return;}int count=it.getAmount();long total=Math.multiplyExact(price,count);try{ItemStack removed=it.clone();p.getInventory().setItemInMainHand(null);try{economy.adjust(p.getUniqueId(),p.getName(),total,"SHOP_SELL");}catch(Exception failure){p.getInventory().setItemInMainHand(removed);throw failure;}msg(p,"Sold "+count+" × "+it.getType()+" for "+money(total)+".");}catch(Exception e){msg(p,"§c"+safe(e));}}
 private void buyShopItem(Player p,Material m,int qty){org.bukkit.configuration.file.YamlConfiguration y=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(new File(getDataFolder(),"shop.yml"));long price=-1;for(String cat:y.getConfigurationSection("categories").getKeys(false)){price=y.getLong("categories."+cat+".items."+m.name()+".buy",-1);if(price>=0)break;}if(price<=0){msg(p,"This item is not for sale.");return;}if(qty<1||qty>getConfig().getInt("limits.max-shop-quantity",64))return;long total=Math.multiplyExact(price,qty);if(p.getInventory().firstEmpty()==-1){msg(p,"Your inventory is full.");return;}try{db.tx(c->{try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance-? WHERE uuid=? AND balance>=?")){q.setLong(1,total);q.setString(2,p.getUniqueId().toString());q.setLong(3,total);if(q.executeUpdate()!=1)throw new IllegalStateException("Insufficient funds.");}mail(c,p.getUniqueId(),"GOODS",m.name()+"|"+qty);EconomyService.log(c,p.getUniqueId(),"SHOP_BUY",-total,m+" x"+qty);return null;});msg(p,"Purchased "+qty+" × "+m+" for "+money(total)+". Delivery added to your claim mailbox if your inventory is full.");claim(p);}catch(Exception e){msg(p,"§c"+safe(e));}}

 private void opshop(Player p,String[] a)throws Exception{if(a.length==0||a[0].equalsIgnoreCase("status")){msg(p,manager(p.getUniqueId())?"You own permanent §c[Manager]":"Custom Manager price: §6"+money(getConfig().getLong("manager.price")));return;}if(!a[0].equalsIgnoreCase("buy")){msg(p,"Usage: /opshop [buy|status]");return;}long cost=getConfig().getLong("manager.price");db.tx(c->{try(PreparedStatement q=c.prepareStatement("SELECT 1 FROM managers WHERE uuid=?")){q.setString(1,p.getUniqueId().toString());try(ResultSet r=q.executeQuery()){if(r.next())throw new IllegalStateException("You already own Custom Manager.");}}try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance-? WHERE uuid=? AND balance>=?")){q.setLong(1,cost);q.setString(2,p.getUniqueId().toString());q.setLong(3,cost);if(q.executeUpdate()!=1)throw new IllegalStateException("Insufficient funds.");}try(PreparedStatement q=c.prepareStatement("INSERT INTO managers(uuid,purchased_at) VALUES(?,?)")){q.setString(1,p.getUniqueId().toString());q.setLong(2,System.currentTimeMillis());q.executeUpdate();}EconomyService.log(c,p.getUniqueId(),"MANAGER_PURCHASE",-cost,"Custom Manager");return null;});refreshName(p);attachManagerPermissions(p);msg(p,"§aYou purchased permanent §c[Manager]§a. No Bukkit OP was granted.");}
 private void hop(Player p,String[] a){if(!manager(p.getUniqueId())){noPerm(p);return;}if(a.length==0||a[0].equalsIgnoreCase("help")){msg(p,"/hop fly | gm <mode> | tp <player> | heal | feed | give <item> <amount>");return;}String power=a[0].toLowerCase(Locale.ROOT);String permPower=power.equals("gm")?"gamemode":(power.equals("tp")?"teleport":power);if(!getConfig().getBoolean("manager.powers."+permPower,true)||!p.hasPermission("horizeneconomy.manager."+permPower)){msg(p,"This Manager power is disabled or not permitted.");return;}switch(power){case "fly"->{p.setAllowFlight(!p.getAllowFlight());p.setFlying(p.getAllowFlight());msg(p,"Flight: "+p.getAllowFlight());}case "gm"->{if(a.length<2||!p.hasPermission("horizeneconomy.manager.gamemode")){noPerm(p);return;}GameMode gm;try{gm=GameMode.valueOf(a[1].toUpperCase(Locale.ROOT));}catch(Exception e){msg(p,"Use survival, creative, adventure or spectator.");return;}p.setGameMode(gm);}case "tp"->{if(a.length<2){msg(p,"/hop tp <player>");return;}Player t=Bukkit.getPlayerExact(a[1]);if(t==null){msg(p,"Player is not online.");return;}p.teleport(t.getLocation());}case "heal"->{p.setHealth(p.getMaxHealth());p.setFireTicks(0);}case "feed"->{p.setFoodLevel(20);p.setSaturation(20);}case "give"->{if(a.length<3){msg(p,"/hop give <material> <amount>");return;}Material m=Material.matchMaterial(a[1]);int n;try{n=Integer.parseInt(a[2]);}catch(Exception e){n=0;}if(m==null||m.isAir()||n<1||n>64){msg(p,"Invalid item or amount (1-64).");return;}p.getInventory().addItem(new ItemStack(m,n));}default->msg(p,"Unknown Manager command.");}}

 private void order(Player p,String[] a)throws Exception{if(a.length==0){msg(p,"/order unlock | create <material> <amount> <unit-price> | browse | accept <id> [amount] | cancel <id> | history");return;}switch(a[0].toLowerCase(Locale.ROOT)){
  case "unlock"->{unlock(p,"orders",getConfig().getLong("orders.unlock-price"));}
  case "create"->{requireUnlock(p,"orders");if(a.length!=4){msg(p,"/order create <material> <amount> <unit-price>");return;}Material m=Material.matchMaterial(a[1]);if(m==null||m.isAir())throw new IllegalArgumentException("Invalid item material.");int qty=Integer.parseInt(a[2]);long unit=amount(a[3]);if(qty<1||qty>64)throw new IllegalArgumentException("Quantity must be 1-64 per order.");long total=Math.multiplyExact(unit,qty);String id=randomId("O");long now=System.currentTimeMillis(),expires=now+getConfig().getLong("orders.expiry-hours",168)*3600000L;
   db.tx(c->{try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance-? WHERE uuid=? AND balance>=?")){q.setLong(1,total);q.setString(2,p.getUniqueId().toString());q.setLong(3,total);if(q.executeUpdate()!=1)throw new IllegalStateException("Insufficient funds for escrow.");}try(PreparedStatement q=c.prepareStatement("INSERT INTO orders(id,owner,material,amount,remaining,unit_price,escrow,state,created_at,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?)")){q.setString(1,id);q.setString(2,p.getUniqueId().toString());q.setString(3,m.name());q.setInt(4,qty);q.setInt(5,qty);q.setLong(6,unit);q.setLong(7,total);q.setString(8,"OPEN");q.setLong(9,now);q.setLong(10,expires);q.executeUpdate();}EconomyService.log(c,p.getUniqueId(),"ORDER_ESCROW",-total,"order="+id);return null;});msg(p,"Order §d"+id+" §acreated anonymously. Escrow: "+money(total)+".");}
  case "browse"->{requireUnlock(p,"orders");browseOrders(p);}
  case "accept"->{requireUnlock(p,"orders");if(a.length<2){msg(p,"/order accept <id> [quantity]");return;}int q=a.length>2?Integer.parseInt(a[2]):Integer.MAX_VALUE;acceptOrder(p,a[1].toUpperCase(Locale.ROOT),q);}
  case "cancel"->{if(a.length<2)return;cancelOrder(p,a[1].toUpperCase(Locale.ROOT));}
  case "history"->{orderHistory(p);}
  default->msg(p,"Unknown order action.");}}
 private void unlock(Player p,String market,long price)throws SQLException{if(db.unlocked(p.getUniqueId(),market)){msg(p,"You already have permanent access.");return;}db.tx(c->{try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance-? WHERE uuid=? AND balance>=?")){q.setLong(1,price);q.setString(2,p.getUniqueId().toString());q.setLong(3,price);if(q.executeUpdate()!=1)throw new IllegalStateException("You need "+money(price)+" to unlock this market.");}try(PreparedStatement q=c.prepareStatement("INSERT INTO unlocks(uuid,market) VALUES(?,?)")){q.setString(1,p.getUniqueId().toString());q.setString(2,market);q.executeUpdate();}EconomyService.log(c,p.getUniqueId(),market.toUpperCase(Locale.ROOT)+"_UNLOCK",-price,"permanent unlock");return null;});msg(p,"§aPermanent "+market+" access unlocked!");}
 private void requireUnlock(Player p,String market)throws SQLException{if(!db.unlocked(p.getUniqueId(),market))throw new IllegalStateException("Unlock /"+market+" first. Price: "+money(getConfig().getLong(market.equals("orders")?"orders.unlock-price":"auctions.unlock-price"))+".");}
 private String randomId(String prefix){String alphabet="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";StringBuilder b=new StringBuilder(prefix);for(int i=0;i<7;i++)b.append(alphabet.charAt(ThreadLocalRandom.current().nextInt(alphabet.length())));return b.toString();}
 private void browseOrders(Player p)throws SQLException{msg(p,"§d§lAnonymous open orders (no player identities are shown):");try(PreparedStatement q=db.raw().prepareStatement("SELECT id,material,remaining,unit_price,expires_at FROM orders WHERE state='OPEN' AND expires_at>? ORDER BY created_at DESC LIMIT 20")){q.setLong(1,System.currentTimeMillis());try(ResultSet r=q.executeQuery()){while(r.next())msg(p,"§d"+r.getString(1)+" §f"+r.getString(2)+" ×"+r.getInt(3)+" §7at §6"+money(r.getLong(4))+" each §8(expires "+new Date(r.getLong(5))+")");}}}
 private void acceptOrder(Player seller,String id,int requested)throws Exception{ItemStack[] removed={null};try{db.tx(c->{String owner,material;int remaining;long unit;try(PreparedStatement q=c.prepareStatement("SELECT owner,material,remaining,unit_price FROM orders WHERE id=? AND state='OPEN' AND expires_at>?")){q.setString(1,id);q.setLong(2,System.currentTimeMillis());try(ResultSet r=q.executeQuery()){if(!r.next())throw new IllegalStateException("Order not found or expired.");owner=r.getString(1);material=r.getString(2);remaining=r.getInt(3);unit=r.getLong(4);}}
  if(owner.equals(seller.getUniqueId().toString()))throw new IllegalStateException("You cannot fulfil your own order.");int qty=Math.min(remaining,requested);if(qty<1)throw new IllegalStateException("Invalid quantity.");if(!getConfig().getBoolean("orders.partial-fulfilment",true)&&qty<remaining)throw new IllegalStateException("Partial fulfilment is disabled.");Material m=Material.valueOf(material);if(!hasItems(seller,m,qty))throw new IllegalStateException("You do not have enough matching items.");long total=Math.multiplyExact(unit,qty);removed[0]=new ItemStack(m,qty);removeItems(seller,m,qty);
  try(PreparedStatement q=c.prepareStatement("UPDATE orders SET remaining=remaining-?,escrow=escrow-?,state=CASE WHEN remaining-?=0 THEN 'FILLED' ELSE 'OPEN' END WHERE id=? AND state='OPEN' AND remaining>=?")){q.setInt(1,qty);q.setLong(2,total);q.setInt(3,qty);q.setString(4,id);q.setInt(5,qty);if(q.executeUpdate()!=1)throw new IllegalStateException("Order changed; retry.");}
  try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance+? WHERE uuid=?")){q.setLong(1,total);q.setString(2,seller.getUniqueId().toString());q.executeUpdate();}
  mail(c,UUID.fromString(owner),"GOODS",material+"|"+qty);try(PreparedStatement q=c.prepareStatement("INSERT INTO order_history(order_id,owner,counterparty,quantity,total,created_at) VALUES(?,?,?,?,?,?)")){q.setString(1,id);q.setString(2,owner);q.setString(3,seller.getUniqueId().toString());q.setInt(4,qty);q.setLong(5,total);q.setLong(6,System.currentTimeMillis());q.executeUpdate();}EconomyService.log(c,seller.getUniqueId(),"ORDER_FULFILLED",total,"order="+id+" qty="+qty);return null;});}catch(Exception failure){if(removed[0]!=null)seller.getInventory().addItem(removed[0]);throw failure;}msg(seller,"§aFulfilled anonymous order "+id+". Payment was credited; buyer goods are available through /auction claim.");}
 private boolean hasItems(Player p,Material m,int qty){int n=0;for(ItemStack it:p.getInventory().getStorageContents())if(it!=null&&it.getType()==m&&!it.hasItemMeta())n+=it.getAmount();return n>=qty;}
 private void removeItems(Player p,Material m,int qty){for(int i=0;i<p.getInventory().getStorageContents().length&&qty>0;i++){ItemStack it=p.getInventory().getItem(i);if(it==null||it.getType()!=m||it.hasItemMeta())continue;int take=Math.min(qty,it.getAmount());it.setAmount(it.getAmount()-take);qty-=take;if(it.getAmount()==0)p.getInventory().setItem(i,null);}}
 private void cancelOrder(Player p,String id)throws SQLException{db.tx(c->{long refund;try(PreparedStatement q=c.prepareStatement("SELECT escrow FROM orders WHERE id=? AND owner=? AND state='OPEN'")){q.setString(1,id);q.setString(2,p.getUniqueId().toString());try(ResultSet r=q.executeQuery()){if(!r.next())throw new IllegalStateException("Open order not found for your account.");refund=r.getLong(1);}}try(PreparedStatement q=c.prepareStatement("UPDATE orders SET state='CANCELLED',escrow=0 WHERE id=? AND owner=? AND state='OPEN'")){q.setString(1,id);q.setString(2,p.getUniqueId().toString());if(q.executeUpdate()!=1)throw new IllegalStateException("Order changed; retry.");}try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance+? WHERE uuid=?")){q.setLong(1,refund);q.setString(2,p.getUniqueId().toString());q.executeUpdate();}EconomyService.log(c,p.getUniqueId(),"ORDER_REFUND",refund,"order="+id);return null;});msg(p,"Order cancelled. Escrow refund credited to your wallet.");}
 private void orderHistory(Player p)throws SQLException{msg(p,"§dYour private order history:");try(PreparedStatement q=db.raw().prepareStatement("SELECT order_id,quantity,total,created_at FROM order_history WHERE owner=? OR counterparty=? ORDER BY id DESC LIMIT 15")){q.setString(1,p.getUniqueId().toString());q.setString(2,p.getUniqueId().toString());try(ResultSet r=q.executeQuery()){while(r.next())msg(p,"§7"+r.getString(1)+" §f×"+r.getInt(2)+" §6"+money(r.getLong(3))+" §8"+new Date(r.getLong(4)));}}}

 private void auction(Player p,String[] a)throws Exception{if(a.length==0){msg(p,"/auction unlock | create <item> <amount> <starting-price> | browse | bid <id> <amount> | cancel <id> | history | claim");return;}switch(a[0].toLowerCase(Locale.ROOT)){
  case "unlock"->unlock(p,"auctions",getConfig().getLong("auctions.unlock-price"));
  case "create"->{requireUnlock(p,"auctions");if(a.length!=4)throw new IllegalArgumentException("/auction create <item> <amount> <starting-price>");Material requested=Material.matchMaterial(a[1]);int qty=Integer.parseInt(a[2]);long start=amount(a[3]);ItemStack hand=p.getInventory().getItemInMainHand();if(requested==null||hand.getType()!=requested||qty<1||qty>hand.getAmount())throw new IllegalArgumentException("Hold the specified item in your main hand; quantity must be available.");ItemStack offered=hand.clone();offered.setAmount(qty);String blob=encodeItem(offered);String id=randomId("A");long now=System.currentTimeMillis(),expires=now+getConfig().getLong("auctions.duration-hours",24)*3600000L;
   if(hand.getAmount()==qty)p.getInventory().setItemInMainHand(null);else hand.setAmount(hand.getAmount()-qty);try{db.tx(c->{try(PreparedStatement q=c.prepareStatement("INSERT INTO auctions(id,seller,material,amount,item_blob,current_bid,bidder,state,created_at,expires_at) VALUES(?,?,?,?,?,?,NULL,'OPEN',?,?)")){q.setString(1,id);q.setString(2,p.getUniqueId().toString());q.setString(3,offered.getType().name());q.setInt(4,qty);q.setString(5,blob);q.setLong(6,start);q.setLong(7,now);q.setLong(8,expires);q.executeUpdate();}return null;});}catch(Exception failure){p.getInventory().addItem(offered);throw failure;}msg(p,"Auction §d"+id+" created anonymously. Starting bid: "+money(start)+".");}
  case "browse"->{requireUnlock(p,"auctions");browseAuctions(p);}
  case "bid"->{requireUnlock(p,"auctions");if(a.length!=3)throw new IllegalArgumentException("/auction bid <id> <amount>");bid(p,a[1].toUpperCase(Locale.ROOT),amount(a[2]));}
  case "cancel"->{if(a.length<2)return;cancelAuction(p,a[1].toUpperCase(Locale.ROOT));}
  case "history"->auctionHistory(p);
  case "claim"->claim(p);
  default->msg(p,"Unknown auction action.");}}
 private String encodeItem(ItemStack item)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();try(BukkitObjectOutputStream out=new BukkitObjectOutputStream(b)){out.writeObject(item);}return Base64.getEncoder().encodeToString(b.toByteArray());}
 private ItemStack decodeItem(String blob)throws IOException,ClassNotFoundException{byte[] b=Base64.getDecoder().decode(blob);try(BukkitObjectInputStream in=new BukkitObjectInputStream(new ByteArrayInputStream(b))){return (ItemStack)in.readObject();}}
 private void browseAuctions(Player p)throws SQLException{msg(p,"§d§lAnonymous auctions — seller and bidder identities are hidden:");try(PreparedStatement q=db.raw().prepareStatement("SELECT id,material,amount,current_bid,bidder,expires_at FROM auctions WHERE state='OPEN' AND expires_at>? ORDER BY expires_at ASC LIMIT 20")){q.setLong(1,System.currentTimeMillis());try(ResultSet r=q.executeQuery()){while(r.next()){long current=r.getLong(4);String bidder=r.getString(5);msg(p,"§d"+r.getString(1)+" §f"+r.getString(2)+" ×"+r.getInt(3)+" §7Current: §6"+money(current)+" §7Next minimum: §6"+money(bidder==null?current:current+1)+" §8expires "+new Date(r.getLong(6)));}}}}
 private void bid(Player bidder,String id,long bid)throws SQLException{db.tx(c->{String seller,oldBidder;long old;long expiry;try(PreparedStatement q=c.prepareStatement("SELECT seller,current_bid,bidder,expires_at FROM auctions WHERE id=? AND state='OPEN'")){q.setString(1,id);try(ResultSet r=q.executeQuery()){if(!r.next())throw new IllegalStateException("Auction not found.");seller=r.getString(1);old=r.getLong(2);oldBidder=r.getString(3);expiry=r.getLong(4);}}
  if(seller.equals(bidder.getUniqueId().toString()))throw new IllegalStateException("You cannot bid on your own auction.");if(expiry<=System.currentTimeMillis())throw new IllegalStateException("Auction has expired.");long minimum=oldBidder==null?old:Math.addExact(old,1);if(bid<minimum)throw new IllegalStateException("Minimum next bid is "+money(minimum)+".");
  try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance-? WHERE uuid=? AND balance>=?")){q.setLong(1,bid);q.setString(2,bidder.getUniqueId().toString());q.setLong(3,bid);if(q.executeUpdate()!=1)throw new IllegalStateException("Insufficient funds.");}
  if(oldBidder!=null){try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance+? WHERE uuid=?")){q.setLong(1,old);q.setString(2,oldBidder);q.executeUpdate();}}
  try(PreparedStatement q=c.prepareStatement("UPDATE auctions SET current_bid=?,bidder=?,expires_at=? WHERE id=? AND state='OPEN' AND current_bid=?")){q.setLong(1,bid);q.setString(2,bidder.getUniqueId().toString());long newExpiry=expiry;if(getConfig().getBoolean("auctions.anti-sniping-enabled",true)&&expiry-System.currentTimeMillis()<=getConfig().getLong("auctions.anti-sniping-seconds",120)*1000L)newExpiry=System.currentTimeMillis()+getConfig().getLong("auctions.anti-sniping-extension-seconds",120)*1000L;q.setLong(3,newExpiry);q.setString(4,id);q.setLong(5,old);if(q.executeUpdate()!=1)throw new IllegalStateException("Auction changed; retry your bid.");}
  try(PreparedStatement q=c.prepareStatement("INSERT INTO auction_bids(auction_id,bidder,amount,created_at) VALUES(?,?,?,?)")){q.setString(1,id);q.setString(2,bidder.getUniqueId().toString());q.setLong(3,bid);q.setLong(4,System.currentTimeMillis());q.executeUpdate();}EconomyService.log(c,bidder.getUniqueId(),"AUCTION_BID_ESCROW",-bid,"auction="+id);if(oldBidder!=null)EconomyService.log(c,UUID.fromString(oldBidder),"AUCTION_OUTBID_REFUND",old,"auction="+id);return null;});msg(bidder,"Bid accepted anonymously for auction "+id+".");}
 private void cancelAuction(Player p,String id)throws SQLException{db.tx(c->{String blob;try(PreparedStatement q=c.prepareStatement("SELECT item_blob FROM auctions WHERE id=? AND seller=? AND state='OPEN' AND (bidder IS NULL OR bidder='')")){q.setString(1,id);q.setString(2,p.getUniqueId().toString());try(ResultSet r=q.executeQuery()){if(!r.next())throw new IllegalStateException("Auction not found, not yours, or has active bids.");blob=r.getString(1);}}try(PreparedStatement q=c.prepareStatement("UPDATE auctions SET state='CANCELLED' WHERE id=? AND seller=? AND state='OPEN' AND (bidder IS NULL OR bidder='')")){q.setString(1,id);q.setString(2,p.getUniqueId().toString());if(q.executeUpdate()!=1)throw new IllegalStateException("Auction changed; retry.");}mail(c,p.getUniqueId(),"ITEM",blob);return null;});msg(p,"Auction cancelled. Item placed in your private claim mailbox.");}
 private void auctionHistory(Player p)throws SQLException{msg(p,"§dYour private auction history:");try(PreparedStatement q=db.raw().prepareStatement("SELECT auction_id,amount,created_at FROM auction_bids WHERE bidder=? ORDER BY id DESC LIMIT 15")){q.setString(1,p.getUniqueId().toString());try(ResultSet r=q.executeQuery()){while(r.next())msg(p,"§7"+r.getString(1)+" §6"+money(r.getLong(2))+" §8"+new Date(r.getLong(3)));}}}
 private static void mail(Connection c,UUID id,String kind,String payload)throws SQLException{try(PreparedStatement q=c.prepareStatement("INSERT INTO mailbox(uuid,kind,payload,created_at) VALUES(?,?,?,?)")){q.setString(1,id.toString());q.setString(2,kind);q.setString(3,payload);q.setLong(4,System.currentTimeMillis());q.executeUpdate();}}
 private void claim(Player p)throws Exception{int count=0;org.bukkit.NamespacedKey key=new org.bukkit.NamespacedKey(this,"mail-id");try(PreparedStatement q=db.raw().prepareStatement("SELECT id,kind,payload FROM mailbox WHERE uuid=? AND claimed=0 ORDER BY id")){q.setString(1,p.getUniqueId().toString());try(ResultSet r=q.executeQuery()){while(r.next()){int id=r.getInt(1);String kind=r.getString(2),payload=r.getString(3);boolean already=false;for(ItemStack existing:p.getInventory().getContents()){if(existing!=null&&existing.hasItemMeta()&&Integer.toString(id).equals(existing.getItemMeta().getPersistentDataContainer().get(key,org.bukkit.persistence.PersistentDataType.STRING))){already=true;break;}}if(!already){ItemStack deliver;if(kind.equals("ITEM"))deliver=decodeItem(payload);else if(kind.equals("GOODS")){String[] bits=payload.split("\\|",2);Material material=Material.matchMaterial(bits[0]);int qty=Integer.parseInt(bits[1]);if(material==null||qty<1||qty>23040){msg(p,"Invalid mailbox delivery; contact an administrator.");continue;}deliver=new ItemStack(material,qty);}else continue;int slot=p.getInventory().firstEmpty();if(slot<0){msg(p,"Inventory full; remaining items stay in your mailbox.");break;}ItemMeta meta=deliver.getItemMeta();meta.getPersistentDataContainer().set(key,org.bukkit.persistence.PersistentDataType.STRING,Integer.toString(id));deliver.setItemMeta(meta);p.getInventory().setItem(slot,deliver);p.saveData();}try(PreparedStatement u=db.raw().prepareStatement("UPDATE mailbox SET claimed=1 WHERE id=? AND claimed=0")){u.setInt(1,id);u.executeUpdate();}count++;}}}if(count>0)msg(p,"Claimed "+count+" mailbox delivery/deliveries.");}
 private void settleExpired(){if(db==null)return;try{db.tx(c->{List<String> ids=new ArrayList<>();try(PreparedStatement q=c.prepareStatement("SELECT id FROM auctions WHERE state='OPEN' AND expires_at<=?")){q.setLong(1,System.currentTimeMillis());try(ResultSet r=q.executeQuery()){while(r.next())ids.add(r.getString(1));}}
  for(String id:ids){String seller,bidder,blob;long bid;try(PreparedStatement q=c.prepareStatement("SELECT seller,bidder,item_blob,current_bid FROM auctions WHERE id=? AND state='OPEN'")){q.setString(1,id);try(ResultSet r=q.executeQuery()){if(!r.next())continue;seller=r.getString(1);bidder=r.getString(2);blob=r.getString(3);bid=r.getLong(4);}}
   try(PreparedStatement q=c.prepareStatement("UPDATE auctions SET state='SETTLED' WHERE id=? AND state='OPEN'")){q.setString(1,id);if(q.executeUpdate()!=1)continue;}
   if(bidder==null){mail(c,UUID.fromString(seller),"ITEM",blob);}else{java.math.BigDecimal pct=java.math.BigDecimal.valueOf(Math.max(0,getConfig().getDouble("auctions.commission-percent",0)));long commission=java.math.BigDecimal.valueOf(bid).multiply(pct).divide(java.math.BigDecimal.valueOf(100),0,java.math.RoundingMode.DOWN).longValue();long payout=bid-commission;try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance+? WHERE uuid=?")){q.setLong(1,payout);q.setString(2,seller);q.executeUpdate();}mail(c,UUID.fromString(bidder),"ITEM",blob);EconomyService.log(c,UUID.fromString(seller),"AUCTION_SALE",payout,"auction="+id+" commission="+commission);}
  }return null;});}catch(Exception e){getLogger().severe("Auction settlement failed: "+e.getMessage());}}

 @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p)||!(e.getView().getTopInventory().getHolder() instanceof MenuHolder h))return;if(h.menu().equals("storage"))return;e.setCancelled(true);if(e.getRawSlot()<0||e.getRawSlot()>=e.getView().getTopInventory().getSize())return;int slot=e.getRawSlot();String menu=h.menu();try{
  if(menu.equals("bank")){if(slot==22){bankHistory(p);}else if(slot==11){chatActions.put(p.getUniqueId(),"deposit");p.closeInventory();msg(p,"Type the whole-number amount to deposit in chat.");}else if(slot==15){chatActions.put(p.getUniqueId(),"withdraw");p.closeInventory();msg(p,"Type the whole-number amount to withdraw in chat.");}}
  else if(menu.equals("shop")){if(slot==49){p.closeInventory();return;}if(slot==29){if(db.unlocked(p.getUniqueId(),"orders"))openMarket(p,"orders");else openUnlockConfirm(p,"orders");}else if(slot==33){if(db.unlocked(p.getUniqueId(),"auctions"))openMarket(p,"auctions");else openUnlockConfirm(p,"auctions");}else{String[] cats={"Farming","Commands","Gear","Ores"};int[] slots={10,12,14,16};for(int i=0;i<cats.length;i++)if(slot==slots[i]){openCategory(p,cats[i]);break;}}}
  else if(menu.startsWith("category:")){if(slot==49){openShop(p);return;}ItemStack clicked=e.getCurrentItem();if(clicked==null||clicked.getType().isAir())return;int qty=e.isShiftClick()?Math.min(64,getConfig().getInt("limits.max-shop-quantity",64)):1;if(e.isRightClick())sellOne(p,clicked.getType());else {long price=shopPrice(clicked.getType(),true);if(price>=getConfig().getLong("shop.confirmation-threshold",10000))openBuyConfirm(p,clicked.getType(),qty,price);else buyShopItem(p,clicked.getType(),qty);}}
  else if(menu.startsWith("unlock:")){String market=menu.substring(7);if(slot==11)unlock(p,market,getConfig().getLong(market.equals("orders")?"orders.unlock-price":"auctions.unlock-price"));else if(slot==15)openShop(p);}
  else if(menu.startsWith("market:")){String market=menu.substring(7);if(slot==11){if(market.equals("orders"))order(p,new String[]{"browse"});else auction(p,new String[]{"browse"});}else if(slot==15){if(market.equals("orders"))msg(p,"Create an order with /order create <material> <amount> <unit-price>.");else msg(p,"Hold an item and use /auction create <item> <amount> <starting-price>.");}else if(slot==22){if(market.equals("orders"))order(p,new String[]{"history"});else auction(p,new String[]{"history"});}}
  else if(menu.startsWith("confirmbuy:")){if(slot==11){String[] parts=menu.split(":");buyShopItem(p,Material.valueOf(parts[1]),Integer.parseInt(parts[2]));}else p.closeInventory();}
  else if(menu.equals("upgrade")){int[] slots={10,13,16};String[] kinds={"ender-storage","homes","sell-limit"};for(int i=0;i<slots.length;i++)if(slot==slots[i]){if(kinds[i].equals("ender-storage")&&db.upgrade(p.getUniqueId(),kinds[i])>0)openStorage(p);else purchaseUpgrade(p,kinds[i]);}}
  else if(menu.equals("adminshop")){if(!manager(p.getUniqueId()))return;ItemStack it=e.getCurrentItem();if(it!=null&&!it.getType().isAir()){if(getConfig().getBoolean("manager.admin-shop-free",true)){if(p.getInventory().firstEmpty()<0){msg(p,"Inventory full.");return;}p.getInventory().addItem(new ItemStack(it.getType()));}else msg(p,"Admin shop pricing is not configured.");}}
 }catch(Exception ex){msg(p,"§c"+safe(ex));}}
 @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof MenuHolder h&&!h.menu().equals("storage"))e.setCancelled(true);}
 @EventHandler public void closeStorage(InventoryCloseEvent e){if(e.getInventory().getHolder() instanceof MenuHolder h&&h.menu().equals("storage")&&e.getPlayer() instanceof Player p)saveStorage(p,e.getInventory());}
 private void sellOne(Player p,Material m){ItemStack found=null;for(ItemStack it:p.getInventory().getStorageContents())if(it!=null&&it.getType()==m&&!it.hasItemMeta()){found=it;break;}if(found==null){msg(p,"You do not have a plain "+m+" to sell.");return;}found.setAmount(found.getAmount()-1);if(found.getAmount()==0)p.getInventory().remove(found);org.bukkit.configuration.file.YamlConfiguration y=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(new File(getDataFolder(),"shop.yml"));long price=-1;for(String cat:y.getConfigurationSection("categories").getKeys(false)){price=y.getLong("categories."+cat+".items."+m.name()+".sell",-1);if(price>=0)break;}if(price>0)try{economy.adjust(p.getUniqueId(),p.getName(),price,"SHOP_SELL");msg(p,"Sold 1 × "+m+" for "+money(price)+".");}catch(Exception ex){msg(p,"§c"+safe(ex));}}
 private void purchaseUpgrade(Player p,String kind)throws Exception{int level=db.upgrade(p.getUniqueId(),kind);List<Integer> prices=getConfig().getIntegerList("upgrades."+kind+".prices");if(level>=prices.size()){msg(p,"This upgrade is already max level.");return;}long cost=prices.get(level);db.tx(c->{try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance-? WHERE uuid=? AND balance>=?")){q.setLong(1,cost);q.setString(2,p.getUniqueId().toString());q.setLong(3,cost);if(q.executeUpdate()!=1)throw new IllegalStateException("Insufficient funds.");}try(PreparedStatement q=c.prepareStatement("INSERT INTO upgrades(uuid,kind,level) VALUES(?,?,1) ON CONFLICT(uuid,kind) DO UPDATE SET level=level+1")){q.setString(1,p.getUniqueId().toString());q.setString(2,kind);q.executeUpdate();}EconomyService.log(c,p.getUniqueId(),"UPGRADE_"+kind.toUpperCase(Locale.ROOT),-cost,"level="+(level+1));return null;});msg(p,"Purchased "+kind+" level "+(level+1)+".");if(kind.equals("ender-storage"))openStorage(p);else openUpgrade(p);}

 private void openUnlockConfirm(Player p,String market){long price=getConfig().getLong(market.equals("orders")?"orders.unlock-price":"auctions.unlock-price");Inventory inv=menu(p,"unlock:"+market,"§0Confirm permanent unlock",27);inv.setItem(11,item(Material.LIME_CONCRETE,"Confirm unlock","§7Permanent access to "+market,"§7Cost: §6"+money(price)));inv.setItem(15,item(Material.RED_CONCRETE,"Cancel"));}
 private void openMarket(Player p,String market){Inventory inv=menu(p,"market:"+market,market.equals("orders")?"§0§5Private Orders":"§0§5Auction House",27);inv.setItem(11,item(Material.BOOK,"Browse listings","§7View anonymous public listings"));inv.setItem(15,item(Material.EMERALD,"Create listing","§7Create a private order or anonymous auction"));inv.setItem(22,item(Material.CHEST,"My history","§7Only you can see your own history"));}
 private void openBuyConfirm(Player p,Material material,int qty,long price){Inventory inv=menu(p,"confirmbuy:"+material.name()+":"+qty,"§0Confirm purchase",27);inv.setItem(11,item(Material.LIME_CONCRETE,"Confirm purchase","§7"+qty+" × "+material,"§7Total: §6"+money(Math.multiplyExact(price,qty))));inv.setItem(15,item(Material.RED_CONCRETE,"Cancel"));}
 private long shopPrice(Material material,boolean buy){org.bukkit.configuration.file.YamlConfiguration y=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(new File(getDataFolder(),"shop.yml"));for(String cat:y.getConfigurationSection("categories").getKeys(false)){long price=y.getLong("categories."+cat+".items."+material.name()+(buy?".buy":".sell"),-1);if(price>=0)return price;}return -1;}
 private void setHome(Player p,String[] a)throws SQLException{if(a.length!=1){msg(p,"Usage: /sethome <name>");return;}String name=a[0].toLowerCase(Locale.ROOT);if(!name.matches("[a-z0-9_-]{1,16}"))throw new IllegalArgumentException("Home names must be 1-16 letters, numbers, _ or -.");int level=db.upgrade(p.getUniqueId(),"homes");int max=1+level;try(PreparedStatement q=db.raw().prepareStatement("SELECT COUNT(*) FROM homes WHERE uuid=?")){q.setString(1,p.getUniqueId().toString());try(ResultSet r=q.executeQuery()){if(r.next()&&r.getInt(1)>=max){try(PreparedStatement e=db.raw().prepareStatement("SELECT 1 FROM homes WHERE uuid=? AND name=?")){e.setString(1,p.getUniqueId().toString());e.setString(2,name);try(ResultSet er=e.executeQuery()){if(!er.next())throw new IllegalStateException("You have reached your home limit ("+max+"). Upgrade /upgrade to add slots.");}}}}}Location l=p.getLocation();try(PreparedStatement q=db.raw().prepareStatement("INSERT INTO homes(uuid,name,world,x,y,z,yaw,pitch) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(uuid,name) DO UPDATE SET world=excluded.world,x=excluded.x,y=excluded.y,z=excluded.z,yaw=excluded.yaw,pitch=excluded.pitch")){q.setString(1,p.getUniqueId().toString());q.setString(2,name);q.setString(3,l.getWorld().getName());q.setDouble(4,l.getX());q.setDouble(5,l.getY());q.setDouble(6,l.getZ());q.setFloat(7,l.getYaw());q.setFloat(8,l.getPitch());q.executeUpdate();}msg(p,"Home '"+name+"' saved.");}
 private void goHome(Player p,String[] a)throws SQLException{if(a.length!=1){msg(p,"Usage: /home <name>");return;}try(PreparedStatement q=db.raw().prepareStatement("SELECT world,x,y,z,yaw,pitch FROM homes WHERE uuid=? AND name=?")){q.setString(1,p.getUniqueId().toString());q.setString(2,a[0].toLowerCase(Locale.ROOT));try(ResultSet r=q.executeQuery()){if(!r.next()){msg(p,"Home not found.");return;}World w=Bukkit.getWorld(r.getString(1));if(w==null){msg(p,"That home's world is not loaded.");return;}p.teleport(new Location(w,r.getDouble(2),r.getDouble(3),r.getDouble(4),r.getFloat(5),r.getFloat(6)));}}}
 private void bankHistory(Player p)throws SQLException{msg(p,"§dYour recent bank transactions:");try(PreparedStatement q=db.raw().prepareStatement("SELECT kind,amount,created_at FROM transactions WHERE uuid=? AND kind LIKE 'BANK_%' ORDER BY id DESC LIMIT 10")){q.setString(1,p.getUniqueId().toString());try(ResultSet r=q.executeQuery()){while(r.next())msg(p,"§7"+r.getString(1)+" §6"+money(Math.abs(r.getLong(2)))+" §8"+new Date(r.getLong(3)));}}}
 private void openStorage(Player p){try{int level=db.upgrade(p.getUniqueId(),"ender-storage");int size=Math.min(54,27+level*9);MenuHolder holder=new MenuHolder("storage");Inventory inv=Bukkit.createInventory(holder,size,"§0§5Personal Storage");holder.setInventory(inv);try(PreparedStatement q=db.raw().prepareStatement("SELECT contents FROM player_storage WHERE uuid=?")){q.setString(1,p.getUniqueId().toString());try(ResultSet r=q.executeQuery()){if(r.next()){ItemStack[] saved=decodeContents(r.getString(1));for(int i=0;i<Math.min(size,saved.length);i++)inv.setItem(i,saved[i]);}}}p.openInventory(inv);}catch(Exception ex){msg(p,"§cCould not open personal storage: "+safe(ex));}}
 private String encodeContents(Inventory inv)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();try(BukkitObjectOutputStream out=new BukkitObjectOutputStream(b)){out.writeObject(inv.getContents());}return Base64.getEncoder().encodeToString(b.toByteArray());}
 private ItemStack[] decodeContents(String data)throws IOException,ClassNotFoundException{try(BukkitObjectInputStream in=new BukkitObjectInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(data)))){return (ItemStack[])in.readObject();}}
 private void saveStorage(Player p,Inventory inv){try{String data=encodeContents(inv);try(PreparedStatement q=db.raw().prepareStatement("INSERT INTO player_storage(uuid,contents) VALUES(?,?) ON CONFLICT(uuid) DO UPDATE SET contents=excluded.contents")){q.setString(1,p.getUniqueId().toString());q.setString(2,data);q.executeUpdate();}}catch(Exception ex){getLogger().severe("Storage save failed for "+p.getUniqueId()+": "+ex.getMessage());}}
 private void maintenance(){settleExpired();expireOrders();processInterest();}
 private void processInterest(){if(!getConfig().getBoolean("bank.interest-enabled",false))return;long period=Math.max(1,getConfig().getLong("bank.interest-period-hours",24))*3600000L;try{db.tx(c->{long last=0;try(PreparedStatement q=c.prepareStatement("SELECT value FROM economy_meta WHERE key='last_interest'")){try(ResultSet r=q.executeQuery()){if(r.next())last=Long.parseLong(r.getString(1));}}long now=System.currentTimeMillis();if(now-last<period)return null;java.math.BigDecimal rate=java.math.BigDecimal.valueOf(Math.max(0,getConfig().getDouble("bank.interest-percent",0.5))).divide(java.math.BigDecimal.valueOf(100),8,java.math.RoundingMode.DOWN);try(PreparedStatement q=c.prepareStatement("SELECT uuid,balance FROM bank WHERE balance>0")){try(ResultSet r=q.executeQuery()){while(r.next()){long interest=java.math.BigDecimal.valueOf(r.getLong(2)).multiply(rate).setScale(0,java.math.RoundingMode.DOWN).longValue();if(interest>0){try(PreparedStatement u=c.prepareStatement("UPDATE bank SET balance=balance+? WHERE uuid=?")){u.setLong(1,interest);u.setString(2,r.getString(1));u.executeUpdate();}EconomyService.log(c,UUID.fromString(r.getString(1)),"BANK_INTEREST",interest,"scheduled interest");}}}}try(PreparedStatement q=c.prepareStatement("INSERT INTO economy_meta(key,value) VALUES('last_interest',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value")){q.setString(1,Long.toString(now));q.executeUpdate();}return null;});}catch(Exception ex){getLogger().severe("Interest processing failed: "+ex.getMessage());}}
 private void expireOrders(){try{db.tx(c->{List<String[]> expired=new ArrayList<>();try(PreparedStatement q=c.prepareStatement("SELECT id,owner,escrow FROM orders WHERE state='OPEN' AND expires_at<=?")){q.setLong(1,System.currentTimeMillis());try(ResultSet r=q.executeQuery()){while(r.next())expired.add(new String[]{r.getString(1),r.getString(2),Long.toString(r.getLong(3))});}}for(String[] row:expired){try(PreparedStatement q=c.prepareStatement("UPDATE orders SET state='EXPIRED',escrow=0 WHERE id=? AND state='OPEN'")){q.setString(1,row[0]);if(q.executeUpdate()!=1)continue;}try(PreparedStatement q=c.prepareStatement("UPDATE wallets SET balance=balance+? WHERE uuid=?")){q.setLong(1,Long.parseLong(row[2]));q.setString(2,row[1]);q.executeUpdate();}EconomyService.log(c,UUID.fromString(row[1]),"ORDER_EXPIRY_REFUND",Long.parseLong(row[2]),"order="+row[0]);}return null;});}catch(Exception ex){getLogger().severe("Order expiry processing failed: "+ex.getMessage());}}
 @Override public List<String> onTabComplete(CommandSender s,Command c,String alias,String[] a){if(a.length==1)return switch(c.getName().toLowerCase(Locale.ROOT)){case "order"->List.of("unlock","create","browse","accept","cancel","history");case "auction"->List.of("unlock","create","browse","bid","cancel","history","claim");case "opshop"->List.of("buy","status");case "hop"->List.of("help","fly","gm","tp","heal","feed","give");case "eco"->List.of("give","take","set","audit");case "bank"->List.of("deposit","withdraw","history");case "sell"->List.of("all","hand");default->List.of();};return List.of();}
}
